"""Clustering evaluation: K-means with ground-truth K, NMI, 10 runs (Sec 5.1)."""

from __future__ import annotations

import numpy as np
from sklearn.cluster import KMeans
from sklearn.impute import SimpleImputer
from sklearn.metrics import normalized_mutual_info_score

DEFAULT_NBINS = [2, 3, 4, 6, 8]      # paper Section 5.1, hyperparameter search
DEFAULT_SEEDS = list(range(10))      # "each experiment was conducted 10 times"


def evaluate_nbins(Z: np.ndarray, y: np.ndarray, K: int, seeds=DEFAULT_SEEDS) -> dict:
    """K-means on the kernel representation; mean/std/per-seed NMI."""
    nmis = []
    for s in seeds:
        km = KMeans(n_clusters=K, init="k-means++", n_init=10, random_state=s)
        labels = km.fit_predict(Z)
        nmis.append(float(normalized_mutual_info_score(y, labels)))
    arr = np.asarray(nmis)
    return {"mean": float(arr.mean()), "std": float(arr.std()), "per_seed": nmis}


def search_nbins(X, y, K, src_builder, nbins_grid=DEFAULT_NBINS, seeds=DEFAULT_SEEDS):
    """Search nbins by mean NMI over the 10 runs (assumption A9)."""
    results = {}
    for nb in nbins_grid:
        Z, diag = src_builder(X, nb)
        res = evaluate_nbins(Z, y, K, seeds)
        results[nb] = {"nmi": res, "diag": diag, "Z_shape": list(Z.shape)}
    best_nbins = max(results, key=lambda nb: results[nb]["nmi"]["mean"])
    return int(best_nbins), results


def baseline_median_nmi(X: np.ndarray, y: np.ndarray, K: int, seeds=DEFAULT_SEEDS) -> dict:
    """Sanity reference: K-means on median-imputed raw features."""
    Xi = SimpleImputer(strategy="median").fit_transform(X)
    return evaluate_nbins(Xi, y, K, seeds)

